package fs

import (
	"context"
	"io"
	"sync"
	"testing"
	"time"

	"go.flipt.io/flipt/internal/containers"
	"go.uber.org/zap"
)

// UpdateFunc checks for changes to a snapshot.
type UpdateFunc func(context.Context) (bool, error)

type Poller struct {
	logger *zap.Logger
	ctx    context.Context
	cancel context.CancelFunc
	update UpdateFunc

	interval time.Duration
	notify   func(modified bool)

	mu      sync.Mutex
	started bool
	closed  bool
	active  sync.WaitGroup
}

var _ io.Closer = (*Poller)(nil)

func WithInterval(interval time.Duration) containers.Option[Poller] {
	return func(p *Poller) {
		p.interval = interval
	}
}

func WithNotify(t *testing.T, n func(modified bool)) containers.Option[Poller] {
	t.Helper()
	return func(p *Poller) {
		p.notify = n
	}
}

func NewPoller(ctx context.Context, logger *zap.Logger, update UpdateFunc, opts ...containers.Option[Poller]) *Poller {
	ctx, cancel := context.WithCancel(ctx)
	p := &Poller{
		logger:   logger,
		ctx:      ctx,
		cancel:   cancel,
		update:   update,
		interval: 30 * time.Second,
	}
	containers.ApplyAll(p, opts...)
	return p
}

// Poll starts the common polling strategy used by declarative store implementations.
// It registers the goroutine before returning so Close can always wait for it.
func (p *Poller) Poll() {
	p.mu.Lock()
	if p.closed || p.started {
		p.mu.Unlock()
		return
	}
	p.started = true
	p.active.Add(1)
	p.mu.Unlock()

	go p.run()
}

func (p *Poller) run() {
	defer p.active.Done()

	ticker := time.NewTicker(p.interval)
	defer ticker.Stop()
	for {
		select {
		case <-p.ctx.Done():
			return
		case <-ticker.C:
			// A tick can be ready at the same time as cancellation.
			if p.ctx.Err() != nil {
				return
			}
			modified, err := p.update(p.ctx)
			if err != nil {
				p.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}

			if p.notify != nil {
				p.notify(modified)
			}

			if !modified {
				p.logger.Debug("skipping snapshot update as it has not been modified")
				continue
			}

			p.logger.Debug("snapshot updated")
		}
	}
}

// Close stops polling and waits for any active Poll calls to return.
func (p *Poller) Close() error {
	p.mu.Lock()
	p.closed = true
	p.cancel()
	p.mu.Unlock()
	p.active.Wait()
	return nil
}
package fs

import (
	"context"
	"sync"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"go.uber.org/zap"
)

func TestPollerCloseWithoutPolling(t *testing.T) {
	p := NewPoller(context.Background(), zap.NewNop(), func(context.Context) (bool, error) {
		t.Fatal("update called after close")
		return false, nil
	}, WithInterval(time.Millisecond))

	require.NoError(t, p.Close())
	p.Poll()
	require.NoError(t, p.Close())
	require.False(t, p.started)
}

func TestPollerCloseWaitsForUpdate(t *testing.T) {
	started := make(chan struct{})
	release := make(chan struct{})
	finished := make(chan struct{})
	var releaseOnce sync.Once

	p := NewPoller(context.Background(), zap.NewNop(), func(ctx context.Context) (bool, error) {
		close(started)
		<-ctx.Done()
		<-release
		close(finished)
		return false, nil
	}, WithInterval(time.Millisecond))
	t.Cleanup(func() {
		releaseOnce.Do(func() { close(release) })
		require.NoError(t, p.Close())
	})

	p.Poll()
	p.Poll() // Starting the same poller again must not start another update loop.
	select {
	case <-started:
	case <-time.After(2 * time.Second):
		t.Fatal("polling did not start")
	}

	closed := make(chan error, 1)
	go func() { closed <- p.Close() }()
	select {
	case <-p.ctx.Done():
	case <-time.After(2 * time.Second):
		t.Fatal("close did not cancel the update context")
	}
	select {
	case <-closed:
		t.Fatal("close returned while update was still running")
	default:
	}

	releaseOnce.Do(func() { close(release) })
	select {
	case <-finished:
	case <-time.After(2 * time.Second):
		t.Fatal("update did not finish")
	}
	select {
	case err := <-closed:
		require.NoError(t, err)
	case <-time.After(2 * time.Second):
		t.Fatal("close did not wait for polling to terminate")
	}
}

